{
  "title": "the_bell_tower_rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party enters through the ruined castle gates.",
      "visual_description": "A massive iron gate hangs half open, its hinges rusted. Weathered royal banners droop from stone battlements. Five figures stand on the cobblestone path, looking up at the crumbling archway.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "bridge_crosser"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper in a collapsed market street.",
      "visual_description": "Narrow street lined with broken stalls and fallen awnings. Shadows hug the walls. A cluster of townspeople huddle near a cracked fountain, pointing at a distant tower.",
      "characters": ["townspeople", "scout"]
    },
    {
      "scene_number": 3,
      "caption": "The scout reports rumors of a dragon to the group.",
      "visual_description": "Inside a roofless stone shelter, the scout gestures urgently. A torn map lies on a low table. The map reader traces a route while the magic helper listens, hand raised.",
      "characters": ["scout", "map_reader", "magic_helper", "sleepy_official", "bridge_crosser"]
    },
    {
      "scene_number": 4,
      "caption": "Armored patrols march along the outer wall.",
      "visual_description": "A line of soldiers in dented plate armor, carrying pikes, files past a cracked tower. The patrol leader glances toward a narrow alley where the group hides.",
      "characters": ["armored_patrol", "scout", "bridge_crosser"]
    },
    {
      "scene_number": 5,
      "caption": "The party finds a magic door sealed with a crystal lock.",
      "visual_description": "A round door of pale blue stone set into a wall of rubble. A crystal keyhole glows faintly. The magic helper touches the surface, sending ripples of light across the door.",
      "characters": ["magic_helper", "map_reader", "bridge_crosser", "sleepy_official"]
    },
    {
      "scene_number": 6,
      "caption": "The sleepy official finds the crystal key in a fountain.",
      "visual_description": "A dry stone fountain in a small plaza. The sleepy official sits on the edge, yawning, one hand dipped into the basin. Among dry leaves a crystal key glints.",
      "characters": ["sleepy_official", "scout"]
    },
    {
      "scene_number": 7,
      "caption": "The magic door opens into a mirror hall.",
      "visual_description": "A long hall lined with tall mirrors, each reflecting a different ruined scene. The floor is black glass. The party steps through the doorway, their reflections multiplied.",
      "characters": ["magic_helper", "map_reader", "scout", "sleepy_official", "bridge_crosser"]
    },
    {
      "scene_number": 8,
      "caption": "A cursed tower looms beyond the mirror hall.",
      "visual_description": "Through an archway at the hall's end, a twisted black tower rises against a bruised sky. Thorny vines crawl up its sides. A single lit window glows near the top.",
      "characters": ["map_reader", "bridge_crosser", "magic_helper"]
    },
    {
      "scene_number": 9,
      "caption": "The scout climbs the tower wall to reach the window.",
      "visual_description": "The scout clings to crumbling stone, hand over hand, a rope coiled at their belt. Below, the party watches from a cracked courtyard. The lit window is just above.",
      "characters": ["scout", "map_reader", "magic_helper", "sleepy_official", "bridge_crosser"]
    },
    {
      "scene_number": 10,
      "caption": "Inside the tower, the rescue begins.",
      "visual_description": "A circular room with a stone bed and a brass lamp. A figure in a travel cloak sits against the wall. The scout drops through the window, landing silently.",
      "characters": ["scout", "rescued_person"]
    },
    {
      "scene_number": 11,
      "caption": "The rescued person is led down the tower stairs.",
      "visual_description": "A narrow spiral staircase, torches flickering. The scout guides the cloaked figure down, each step stirring dust. Below, the magic helper lights the way with a glowing hand.",
      "characters": ["scout", "rescued_person", "magic_helper"]
    },
    {
      "scene_number": 12,
      "caption": "Armored patrols block the old plaza exit.",
      "visual_description": "An open plaza with a broken statue. A line of armored soldiers forms a wall across the far archway. The party emerges from a side street, the rescued person among them.",
      "characters": ["armored_patrol", "map_reader", "scout", "magic_helper", "sleepy_official", "bridge_crosser", "rescued_person"]
    },
    {
      "scene_number": 13,
      "caption": "The magic helper creates a diversion with mirror shards.",
      "visual_description": "A shower of mirror fragments spins into the air, catching torchlight and blinding the patrol. Soldiers shield their eyes. The party slips behind a broken colonnade.",
      "characters": ["magic_helper", "armored_patrol", "map_reader", "scout", "sleepy_official", "bridge_crosser", "rescued_person"]
    },
    {
      "scene_number": 14,
      "caption": "The party reaches the bridge controls.",
      "visual_description": "A stone platform with a rusted lever and gear mechanism overlooking a wide chasm. The bridge is raised. The sleepy official studies the lever, rubbing sleep from their eyes.",
      "characters": ["sleepy_official", "map_reader", "bridge_crosser", "scout", "magic_helper", "rescued_person"]
    },
    {
      "scene_number": 15,
      "caption": "The sleepy official pulls the lever to lower the bridge.",
      "visual_description": "The official grips the lever with both hands, straining. Chains rattle below. The bridge begins to descend, its wooden planks groaning.",
      "characters": ["sleepy_official", "map_reader", "bridge_crosser", "scout", "magic_helper", "rescued_person"]
    },
    {
      "scene_number": 16,
      "caption": "The armored patrol closes in on the bridge platform.",
      "visual_description": "Soldiers charge across the plaza, pikes lowered. The bridge is halfway down. The party stands at the edge, ready to run. The magic helper raises a hand to create a barrier.",
      "characters": ["armored_patrol", "magic_helper", "map_reader", "scout", "sleepy_official", "bridge_crosser", "rescued_person"]
    },
    {
      "scene_number": 17,
      "caption": "The party races across the bridge as it lowers fully.",
      "visual_description": "The bridge slams into the far edge. The party sprints across, planks bouncing. The bridge crosser leads, the rescued person close behind. The patrol halts at the near end.",
      "characters": ["bridge_crosser", "rescued_person", "scout", "map_reader", "magic_helper", "sleepy_official", "armored_patrol"]
    },
    {
      "scene_number": 18,
      "caption": "The escape bridge rises, leaving the ruined city behind.",
      "visual_description": "The bridge retracts, chains pulling it up. The party stands on the far cliff, silhouetted against a sunrise. The ruined city with its towers and banners is small in the distance.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "bridge_crosser", "rescued_person"]
    }
  ]
}
```

